// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Log in with username and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// OidcCallback Redirect target of every identity provider
	// (GET /auth/oidc/callback)
	OidcCallback(ctx context.Context, request OidcCallbackRequestObject) (OidcCallbackResponseObject, error)
	// ListLoginProviders Enabled identity providers for the login page
	// (GET /auth/oidc/providers)
	ListLoginProviders(ctx context.Context, request ListLoginProvidersRequestObject) (ListLoginProvidersResponseObject, error)
	// StartOidcLink Start linking an identity to the logged-in user
	// (GET /auth/oidc/{code}/link)
	StartOidcLink(ctx context.Context, request StartOidcLinkRequestObject) (StartOidcLinkResponseObject, error)
	// StartOidcLogin Start logging in with an identity provider
	// (GET /auth/oidc/{code}/login)
	StartOidcLogin(ctx context.Context, request StartOidcLoginRequestObject) (StartOidcLoginResponseObject, error)
	// ListBudgets Budgets the caller is a member of
	// (GET /budgets)
	ListBudgets(ctx context.Context, request ListBudgetsRequestObject) (ListBudgetsResponseObject, error)
	// CreateBudget Create a budget owned by the caller
	// (POST /budgets)
	CreateBudget(ctx context.Context, request CreateBudgetRequestObject) (CreateBudgetResponseObject, error)
	// GetBudget One budget
	// (GET /budgets/{budgetId})
	GetBudget(ctx context.Context, request GetBudgetRequestObject) (GetBudgetResponseObject, error)
	// UpdateBudget Rename a budget
	// (PUT /budgets/{budgetId})
	UpdateBudget(ctx context.Context, request UpdateBudgetRequestObject) (UpdateBudgetResponseObject, error)
	// ListAccounts Accounts of a budget with their balances
	// (GET /budgets/{budgetId}/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Add an account, with its opening balance
	// (POST /budgets/{budgetId}/accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// ReorderAccounts Set the order of accounts
	// (PUT /budgets/{budgetId}/accounts/order)
	ReorderAccounts(ctx context.Context, request ReorderAccountsRequestObject) (ReorderAccountsResponseObject, error)
	// DeleteAccount Delete an account that has no transactions besides its opening balance
	// (DELETE /budgets/{budgetId}/accounts/{accountId})
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// UpdateAccount Rename, close or reopen an account
	// (PUT /budgets/{budgetId}/accounts/{accountId})
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// GetRegister Every transaction touching an account, with all of their entries
	// (GET /budgets/{budgetId}/accounts/{accountId}/register)
	GetRegister(ctx context.Context, request GetRegisterRequestObject) (GetRegisterResponseObject, error)
	// ListCategories Categories of a budget (flat; build the tree from parentId)
	// (GET /budgets/{budgetId}/categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// CreateCategory Add a category (at most three levels; children take their parent's kind)
	// (POST /budgets/{budgetId}/categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// ReorderCategories Set the order of the categories under one parent
	// (PUT /budgets/{budgetId}/categories/order)
	ReorderCategories(ctx context.Context, request ReorderCategoriesRequestObject) (ReorderCategoriesResponseObject, error)
	// DeleteCategory Delete an unused category (archive it otherwise)
	// (DELETE /budgets/{budgetId}/categories/{categoryId})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// UpdateCategory Rename, archive, or share one envelope among the children
	// (PUT /budgets/{budgetId}/categories/{categoryId})
	UpdateCategory(ctx context.Context, request UpdateCategoryRequestObject) (UpdateCategoryResponseObject, error)
	// SetCategoryBase Set an envelope's base amount per month (:base, ADR-086)
	// (PUT /budgets/{budgetId}/categories/{categoryId}/base)
	SetCategoryBase(ctx context.Context, request SetCategoryBaseRequestObject) (SetCategoryBaseResponseObject, error)
	// MoveCategory Move a category, with its subcategories, under another parent
	// (POST /budgets/{budgetId}/categories/{categoryId}/move)
	MoveCategory(ctx context.Context, request MoveCategoryRequestObject) (MoveCategoryResponseObject, error)
	// GetBudgetMonth The envelopes of one month (ADR-025, ADR-026)
	// (GET /budgets/{budgetId}/months/{month})
	GetBudgetMonth(ctx context.Context, request GetBudgetMonthRequestObject) (GetBudgetMonthResponseObject, error)
	// SetAllocations Set how much the pool gives each envelope in a month
	// (PUT /budgets/{budgetId}/months/{month}/allocations)
	SetAllocations(ctx context.Context, request SetAllocationsRequestObject) (SetAllocationsResponseObject, error)
	// ListPayees Payees, with the category last used for each
	// (GET /budgets/{budgetId}/payees)
	ListPayees(ctx context.Context, request ListPayeesRequestObject) (ListPayeesResponseObject, error)
	// DeletePayee Delete a payee no transaction or schedule uses
	// (DELETE /budgets/{budgetId}/payees/{payeeId})
	DeletePayee(ctx context.Context, request DeletePayeeRequestObject) (DeletePayeeResponseObject, error)
	// RenamePayee Rename a payee
	// (PUT /budgets/{budgetId}/payees/{payeeId})
	RenamePayee(ctx context.Context, request RenamePayeeRequestObject) (RenamePayeeResponseObject, error)
	// MergePayees Merge other payees into this one
	// (POST /budgets/{budgetId}/payees/{payeeId}/merge)
	MergePayees(ctx context.Context, request MergePayeesRequestObject) (MergePayeesResponseObject, error)
	// GetScopeRegister Transactions on a group of accounts, oldest first
	// (GET /budgets/{budgetId}/register)
	GetScopeRegister(ctx context.Context, request GetScopeRegisterRequestObject) (GetScopeRegisterResponseObject, error)
	// ListSchedules The budget's schedules, oldest first
	// (GET /budgets/{budgetId}/schedules)
	ListSchedules(ctx context.Context, request ListSchedulesRequestObject) (ListSchedulesResponseObject, error)
	// SaveSchedules Apply the schedules page's buffer in one database transaction (:w)
	// (POST /budgets/{budgetId}/schedules/batch)
	SaveSchedules(ctx context.Context, request SaveSchedulesRequestObject) (SaveSchedulesResponseObject, error)
	// ListUpcoming Occurrences not yet posted, up to a date (預定 rows, ADR-085)
	// (GET /budgets/{budgetId}/schedules/upcoming)
	ListUpcoming(ctx context.Context, request ListUpcomingRequestObject) (ListUpcomingResponseObject, error)
	// PostOccurrence Post one occurrence now, as it is (:post)
	// (POST /budgets/{budgetId}/schedules/{scheduleId}/post)
	PostOccurrence(ctx context.Context, request PostOccurrenceRequestObject) (PostOccurrenceResponseObject, error)
	// SkipOccurrence Skip one occurrence (:skip)
	// (POST /budgets/{budgetId}/schedules/{scheduleId}/skips)
	SkipOccurrence(ctx context.Context, request SkipOccurrenceRequestObject) (SkipOccurrenceResponseObject, error)
	// UnskipOccurrence Bring a skipped occurrence back (:unskip)
	// (DELETE /budgets/{budgetId}/schedules/{scheduleId}/skips/{occurrence})
	UnskipOccurrence(ctx context.Context, request UnskipOccurrenceRequestObject) (UnskipOccurrenceResponseObject, error)
	// GetBudgetSummary Totals of a budget
	// (GET /budgets/{budgetId}/summary)
	GetBudgetSummary(ctx context.Context, request GetBudgetSummaryRequestObject) (GetBudgetSummaryResponseObject, error)
	// SaveTransactions Apply an editor buffer in one database transaction (:w)
	// (POST /budgets/{budgetId}/transactions/batch)
	SaveTransactions(ctx context.Context, request SaveTransactionsRequestObject) (SaveTransactionsResponseObject, error)
	// MarkReviewed Confirm transactions that need review (:review)
	// (POST /budgets/{budgetId}/transactions/reviewed)
	MarkReviewed(ctx context.Context, request MarkReviewedRequestObject) (MarkReviewedResponseObject, error)
	// GetHealth Whether the API is up and can reach its database
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetHolidays Days off between two years
	// (GET /holidays)
	GetHolidays(ctx context.Context, request GetHolidaysRequestObject) (GetHolidaysResponseObject, error)
	// ImportHolidays Import the government's office calendar from a URL or a CSV text
	// (POST /holidays/import)
	ImportHolidays(ctx context.Context, request ImportHolidaysRequestObject) (ImportHolidaysResponseObject, error)
	// ListHolidayYears The imported years
	// (GET /holidays/years)
	ListHolidayYears(ctx context.Context, request ListHolidayYearsRequestObject) (ListHolidayYearsResponseObject, error)
	// DeleteHolidayYear Forget a year (its days follow the weekend rule again)
	// (DELETE /holidays/years/{year})
	DeleteHolidayYear(ctx context.Context, request DeleteHolidayYearRequestObject) (DeleteHolidayYearResponseObject, error)
	// GetCurrentUser The logged-in user
	// (GET /me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// ListMyIdentities Identities the logged-in user linked
	// (GET /me/identities)
	ListMyIdentities(ctx context.Context, request ListMyIdentitiesRequestObject) (ListMyIdentitiesResponseObject, error)
	// UnlinkMyIdentity Unlink one of the logged-in user's identities
	// (DELETE /me/identities/{id})
	UnlinkMyIdentity(ctx context.Context, request UnlinkMyIdentityRequestObject) (UnlinkMyIdentityResponseObject, error)
	// ChangePassword Set or change the logged-in user's password
	// (PUT /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// GetPreferences The logged-in user's preferences
	// (GET /me/preferences)
	GetPreferences(ctx context.Context, request GetPreferencesRequestObject) (GetPreferencesResponseObject, error)
	// UpdatePreferences Replace the logged-in user's preferences
	// (PUT /me/preferences)
	UpdatePreferences(ctx context.Context, request UpdatePreferencesRequestObject) (UpdatePreferencesResponseObject, error)
	// ListOidcProviders Identity providers (client secrets are never returned)
	// (GET /oidc-providers)
	ListOidcProviders(ctx context.Context, request ListOidcProvidersRequestObject) (ListOidcProvidersResponseObject, error)
	// CreateOidcProvider Add an identity provider (the issuer must serve OIDC discovery)
	// (POST /oidc-providers)
	CreateOidcProvider(ctx context.Context, request CreateOidcProviderRequestObject) (CreateOidcProviderResponseObject, error)
	// DeleteOidcProvider Delete an identity provider (its linked identities are removed)
	// (DELETE /oidc-providers/{id})
	DeleteOidcProvider(ctx context.Context, request DeleteOidcProviderRequestObject) (DeleteOidcProviderResponseObject, error)
	// UpdateOidcProvider Update an identity provider (an empty clientSecret keeps the stored one)
	// (PUT /oidc-providers/{id})
	UpdateOidcProvider(ctx context.Context, request UpdateOidcProviderRequestObject) (UpdateOidcProviderResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
}

// Login operation middleware
func (sh *strictHandler) Login(ctx echo.Context) error {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	var err error
	if binder, ok := ctx.Echo().Binder.(*echo.DefaultBinder); ok {
		// A request validator built on kin-openapi's openapi3filter with
		// KeepValidatedValue leaves the value it validated on the body. Bind
		// that value, matching member names exactly, so the handler receives
		// what was validated instead of a second, case-insensitive decode.
		// Otherwise bind only the request body, so that path and query
		// parameters are not also bound into the body struct.
		if vb, ok := ctx.Request().Body.(interface{ ValidatedValue() any }); !ok || runtime.BindJSONValue(vb.ValidatedValue(), &body) != nil {
			err = binder.BindBody(ctx, &body)
		}
	} else {
		// A custom binder is installed on the Echo instance; defer to it
		// entirely, since echo.Binder does not expose body-only binding and
		// the binder may do more than decode (for example call ctx.Validate).
		err = ctx.Bind(&body)
	}
	if err != nil {
		return err
	}
	request.Body = &body

	handler := func(ctx echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx.Request().Context(), request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		return validResponse.VisitLoginResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

